// Local preview server for the Shopify Custom Section — NOT part of the Vercel deployment and
// not used by the real Shopify theme. Serves shopify/preview.html (generated by
// build-preview.mjs) at "/" and forwards "/api/chat" to the real, unmodified backend handler,
// so the section's fetch() call works exactly as it would once the real endpoint URL is filled
// in on the live theme. Mirrors server.js's setup deliberately, just pointed at the preview file.
//
// Usage: node shopify/build-preview.mjs && node shopify/preview-server.mjs
import dotenv from "dotenv";
import express from "express";
import { fileURLToPath } from "node:url";

const envPath = fileURLToPath(new URL("../.env", import.meta.url));
dotenv.config({ path: envPath, override: true });

const { default: chatHandler } = await import("../api/chat.js");
const app = express();
const previewPath = fileURLToPath(new URL("./preview.html", import.meta.url));

app.use(express.json());
app.all("/api/chat", chatHandler);
app.get("/", (_req, res) => res.sendFile(previewPath));

app.use((err, _req, res, _next) => {
  if (err?.type === "entity.parse.failed" || err instanceof SyntaxError) {
    return res.status(400).json({ error: "Invalid JSON in request body." });
  }
  console.error(err);
  res.status(500).json({ error: "Unexpected server error." });
});

const port = Number(process.env.PREVIEW_PORT || 3100);
app.listen(port, () => {
  console.log(`Shopify section preview running at http://localhost:${port}`);
});
